SELECT "companyid", "status", "name", "industry", "sprating", "islowgrade", "ceo", "addressline1", "addressline2", "postalcode", "city", "stateprov", "country", "description", "foundingdate", "iscurrent", "batchid", "effectivedate", "enddate", CAST(ROW_NUMBER() OVER (ORDER BY companyid, effectivedate) AS INT) AS "sk_companyid" FROM (SELECT TRY_CAST((TRY_CAST(f.CIK AS INT)) AS INT) AS "companyid", TRY_CAST((CAST(f.Status AS TEXT)) AS TEXT) AS "status", TRY_CAST((CAST(f.CompanyName AS TEXT)) AS TEXT) AS "name", TRY_CAST((CAST(i.IN_NAME AS TEXT)) AS TEXT) AS "industry", TRY_CAST((f.SPrating) AS TEXT) AS "sprating", TRY_CAST((CASE WHEN f.SPrating IS NULL THEN NULL WHEN UPPER(f.SPrating) IN ('BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-', 'CC', 'C', 'D') THEN TRUE WHEN UPPER(f.SPrating) IN ('AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-') THEN FALSE ELSE NULL END) AS BOOLEAN) AS "islowgrade", TRY_CAST((f.CEOname) AS TEXT) AS "ceo", TRY_CAST((f.AddrLine1) AS TEXT) AS "addressline1", TRY_CAST((CAST(f.AddrLine2 AS TEXT)) AS TEXT) AS "addressline2", TRY_CAST((CAST(f.PostalCode AS TEXT)) AS TEXT) AS "postalcode", TRY_CAST((CAST(f.City AS TEXT)) AS TEXT) AS "city", TRY_CAST((CAST(f.StateProvince AS TEXT)) AS TEXT) AS "stateprov", TRY_CAST((CAST(f.Country AS TEXT)) AS TEXT) AS "country", TRY_CAST((CAST(f.Description AS TEXT)) AS TEXT) AS "description", TRY_CAST((CAST(STRPTIME(f.FoundingDate, '%Y%m%d') AS DATE)) AS DATE) AS "foundingdate", TRY_CAST((f.PTS = MAX(f.PTS) OVER (PARTITION BY f.CIK)) AS BOOLEAN) AS "iscurrent", TRY_CAST((CAST(NULL AS DECIMAL(5))) AS DECIMAL(5)) AS "batchid", TRY_CAST((CASE WHEN REGEXP_FULL_MATCH(f.PTS, '^[0-9]{8}-[0-9]{6}$') THEN CAST(STRPTIME(f.PTS, '%Y%m%d-%H%M%S') AS DATE) ELSE NULL END) AS DATE) AS "effectivedate", TRY_CAST((CAST('9999-12-31' AS DATE)) AS DATE) AS "enddate" FROM "Source"."FinwireCMP" AS f INNER JOIN "Source"."Industry" AS i ON f.IndustryID = i.IN_ID INNER JOIN "Source"."StatusType" AS s ON f.Status = s.ST_ID);
